  `problem_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Program' COMMENT '题目类型',
  `submit_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交测评的时间',
  `start_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始测评的时间',
  `end_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '结束测评的时间',
  `use_time` int NOT NULL DEFAULT '-1' COMMENT '使用时间',
  `auto_submit` tinyint NOT NULL DEFAULT '-1' COMMENT '自动提交',
  `status` int DEFAULT NULL COMMENT '结果码具体参考文档',
  `error_message` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '错误提醒(编译错误|或者vj提醒)',
  `time` int DEFAULT NULL COMMENT '运行时间(ms)',
  `memory` int DEFAULT NULL COMMENT '运行内存(kb)',
  `score` int DEFAULT '0' COMMENT 'IO判题则不为空',
  `length` int DEFAULT NULL COMMENT '代码长度',
  `flow_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '流程图URL',
  `code` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '代码',
  `reply_options` varchar(3000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '[]' COMMENT '非编程题作答内容',
  `language` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '代码语言',
  `judge_server` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '判题机',
  `submit_ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '提交者所在ip',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `oi_rank_score` int DEFAULT '0' COMMENT 'oi排行榜得分',
  `share_enable` tinyint(1) DEFAULT '0' COMMENT '0为仅自己可见|1为全部人可见。',
  `manual_evaluation` tinyint(1) DEFAULT '0' COMMENT '是否为人工评测',
  `other_judge_submit_id` bigint unsigned DEFAULT NULL COMMENT 'vjudge判题在其它oj的提交id',
  `other_judge_username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'vjudge判题在其它oj的提交用户名',
  `other_judge_password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'vjudge判题在其它oj的提交账号密码',
  `exception_stack_trace` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '异常堆栈信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` enum('T','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'F' COMMENT '是否删除',
  `create_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `update_id` bigint DEFAULT NULL COMMENT '更新人ID',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GLOWXQ' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `judge_unindex` (`judge_key`) USING BTREE,
  UNIQUE KEY `judge_problem_key_uindex` (`problem_key`,`judge_key`) USING BTREE,
  KEY `problem_id_index` (`problem_id`) USING BTREE,
  KEY `user_id_index` (`user_id`) USING BTREE,
  KEY `username_index` (`name`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `judge_problem_id_fk` FOREIGN KEY (`problem_id`) REFERENCES `problem` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `judge_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=391 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='测评记录';


-- ----------------------------
-- Records of `judge`
-- ----------------------------

-- ----------------------------
-- Table structure for `judge_case`
-- ----------------------------
DROP TABLE IF EXISTS `judge_case`;
CREATE TABLE `judge_case` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `judge_id` bigint unsigned NOT NULL COMMENT '提交判题id',
  `judge_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '自定义提交ID',
  `user_id` bigint unsigned NOT NULL COMMENT '用户id',
  `problem_id` bigint unsigned NOT NULL COMMENT '题目ID',
  `problem_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '题目自定义ID',
  `case_id` bigint unsigned DEFAULT NULL COMMENT '测试样例id',
  `status` int DEFAULT NULL COMMENT '具体看结果码',
  `time` int DEFAULT NULL COMMENT '测试该样例所用时间ms',
  `memory` int DEFAULT NULL COMMENT '测试该样例所用空间KB',
  `score` int DEFAULT NULL COMMENT 'IO得分',
  `group_num` int DEFAULT NULL COMMENT 'subtask分组的组号',
  `seq` int DEFAULT NULL COMMENT '排序',
  `mode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'default' COMMENT 'default,subtask_lowest,subtask_average',
  `input_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '样例输入|比赛不可看',
  `output_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '样例输出|比赛不可看',
  `user_output` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '用户样例输出|比赛不可看',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` enum('T','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'F' COMMENT '是否删除',
  `create_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `update_id` bigint DEFAULT NULL COMMENT '更新人ID',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GLOWXQ' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `judge_case_unindex` (`judge_id`,`user_id`,`problem_id`,`case_id`) USING BTREE,
  KEY `judge_case_case_index` (`case_id`) USING BTREE,
  KEY `judge_case_problem_id_index` (`problem_id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `judge_case_judge_id` FOREIGN KEY (`judge_id`) REFERENCES `judge` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `judge_case_problem_id_fx` FOREIGN KEY (`problem_id`) REFERENCES `problem` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=519 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='测评用例情况';


-- ----------------------------
-- Table structure for `judge_server`
-- ----------------------------
DROP TABLE IF EXISTS `judge_server`;
CREATE TABLE `judge_server` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '判题服务名字',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '判题机ip',
  `port` int NOT NULL COMMENT '判题机端口号',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'ip:port',
  `cpu_core` int DEFAULT '0' COMMENT '判题机所在服务器cpu核心数',
  `free_memory` int DEFAULT '0' COMMENT '判题机所在服务器空闲内存',
  `task_number` int NOT NULL DEFAULT '0' COMMENT '当前判题数',
  `max_task_number` int NOT NULL COMMENT '判题并发最大数',
  `enable` tinyint(1) DEFAULT '0' COMMENT '0禁用|1启用',
  `remote_enable` tinyint(1) DEFAULT NULL COMMENT '是否开启远程判题vj',
  `cf_submittable_enable` tinyint(1) DEFAULT '1' COMMENT '是否可提交CF',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` enum('T','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'F' COMMENT '是否删除',
  `create_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `update_id` bigint DEFAULT NULL COMMENT '更新人ID',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GLOWXQ' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `index_judge_url` (`url`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='测评服务';


-- ----------------------------
-- Table structure for `meta_category`
-- ----------------------------
DROP TABLE IF EXISTS `meta_category`;
CREATE TABLE `meta_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `pid` bigint NOT NULL COMMENT '父级ID',
  `deep` bigint DEFAULT NULL COMMENT '层级',
  `sort` bigint DEFAULT NULL COMMENT '排序',
  `enable` tinyint NOT NULL DEFAULT '1' COMMENT '启用',
  `has_children` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否有子级',
  `lock` tinyint NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `del_flag` enum('T','F') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'F' COMMENT '删除标识',
  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `update_id` bigint DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GLOWXQ' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='分类';


