  `pinyin_prefix` varchar(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '拼音前缀',
  `level` int unsigned NOT NULL DEFAULT '0' COMMENT '地址等级',
