  `tenant_id` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'GLOWXQ' COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='区域地址';


-- ----------------------------
-- Records of `meta_region`
-- ----------------------------

-- ----------------------------
-- Table structure for `meta_tag`
-- ----------------------------
