  `text_color` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '#FFFFFF' COMMENT '字体颜色',
  `plain` tinyint(1) NOT NULL DEFAULT '0' COMMENT '镂空样式',
