INSERT INTO `code_monitor` (`id`, `monitor_user_id`, `overlay_user_id`, `monitor_phone`, `overlay_phone`, `monitor_name`, `overlay_name`, `monitor_code`, `overlay_code`, `code_mode`, `monitor_status`, `version`, `create_time`, `update_time`, `del_flag`, `create_id`, `update_id`, `tenant_id`) VALUES
('22', 1, 1, '13667753053', '13667753053', '管理员', '管理员', '#include<bits/stdc++.h>\nusing namespace std;\nint main(){\n    int a,b,c[100000];\n    cin >>a>>b;\n    for(int i =0;i<a+b;i++){\n        cin>>c[i];\n    }\n        for(int i =0;i<a+b;i++){\n       cout <<c[i]<<" ";\n    } \n        return 0;\n}', '#include <iostream>\nusing namespace std;\nint a[1000005];\nint main() {\n	int t,n,max=0;\n	cin>>t;\n	for(int i=1;i<=t;i++){\n		cin>>n;\n		int flag=1;\n		for(int j=1;j<=n;j++){\n			cin>>a[j];\n		}\n        max=0;\n		for(int j=1;j<=n;j++)\n			if(a[j]>max){\n				max=a[j];\n			}\n			\n		\n		for(int j=1;j<=n;j++){\n			if(max%a[j]!=0){\n				flag=0;\n				break;\n			}\n		}\n				\n		\n		\n		if(flag){\n			cout<<"YES"<<endl;\n		}\n		else{\n			cout<<"NO"<<endl;\n		}\n	}\n	\n	\n    return 0;\n}\n', 'OJ', 'MonitorPush', 515, '2025-06-27 00:43:04', '2025-06-27 00:43:04', 'F', NULL, 1, 'GLOWXQ'),
('23', 9, 0, '', '', '管理员', '', '#include<iostream>\nusing namespace std;\nint main() {\n\n     return 0;\n}', '', 'OJ', 'MonitorPush', 1, '2025-06-27 01:09:46', '2025-06-27 01:09:46', 'F', NULL, NULL, 'GLOWXQ'),
('24', 1, 0, '13667753053', '', '管理员', '', '// 画笔测试代码 - C++语法风格\npen.clear();\npen.background(2);\n\n// 基本绘制操作 - for循环\npen.color(1);\npen.move(50, 50);\n\n// 使用for循环绘制正方形\nfor (int i = 0; i < 4; i++) {\n  pen.fd(80);\n  pen.rt(90);\n}\n\n// 使用for循环绘制五角星\nfor (int i = 0; i < 5; i++) {\n  pen.color(i);\n  pen.circle(10);\n  pen.triangleF(15);\n  // Forward 100 pixels\n  pen.fd(100);\n  // Right turn by 144 degrees to form a star\n  pen.rt(144);\n}\n\n// 使用if-else条件判断\npen.move(180, 50);\npen.color("blue");\nfor (int i = 0; i < 8; i++) {\n  if (i % 2 == 0) {\n    pen.color("blue");\n  } else {\n    pen.color("green");\n  }\n  pen.fd(30);\n  pen.rt(45);\n}\n\n// 使用while循环\npen.move(300, 50);\npen.color("purple");\nint j = 0;\nwhile (j < 6) {\n  pen.fd(35);\n  pen.rt(60);\n  j++;\n}\n\n// 使用do-while循环\npen.move(90, 200);\npen.color("orange");\nint k = 0;\ndo {\n  pen.circle(10 + k * 5);\n  pen.move(90, 200 + k * 25);\n  k++;\n} while (k < 4);\n\n// 嵌套循环 - 绘制图案\npen.move(220, 200);\npen.color("teal");\nfor (int row = 0; row < 3; row++) {\n  for (int col = 0; col < 3; col++) {\n    if ((row + col) % 2 == 0) {\n      pen.color("teal");\n      pen.circleF(10);\n    } else {\n      pen.color("magenta");\n      pen.squareF(15);\n    }\n    pen.move(220 + col * 25, 200 + row * 25);\n  }\n}\n\n// switch语句演示\npen.move(350, 200);\nfor (int i = 0; i < 4; i++) {\n  switch (i) {\n    case 0:\n      pen.color("red");\n      pen.fd(35);\n      break;\n    case 1:\n      pen.color("blue");\n      pen.fd(35);\n      break;\n    case 2:\n      pen.color("green");\n      pen.fd(35);\n      break;\n    default:\n      pen.color("black");\n      pen.fd(35);\n      break;\n  }\n  pen.rt(90);\n}\n\n// 三元运算符\npen.move(130, 300);\nfor (int i = 0; i < 6; i++) {\n  pen.color(i % 2 == 0 ? "darkblue" : "darkred");\n  pen.fd(i % 2 == 0 ? 40 : 20);\n  pen.rt(60);\n}\n\n// 复杂条件\npen.move(270, 350);\nfor (int i = 0; i < 8; i++) {\n  if (i > 2 && i < 6) {\n    pen.color("gold");\n  } else if (i == 0 || i == 7) {\n    pen.color("silver");\n  } else {\n    pen.color("bronze");\n  }\n  pen.fd(25);\n  pen.rt(45);\n}\n\n// 画一个螺旋\npen.move(400, 350);\npen.color("deepskyblue");\nfor (int i = 0; i < 20; i++) {\n  pen.fd(2 + i * 1.5);\n  pen.rt(30);\n}\n\npen.finish();', '', 'Glowc', 'MonitorPush', 160, '2025-06-28 01:44:12', '2025-06-28 01:44:12', 'F', NULL, NULL, 'GLOWXQ'),
('25', 9, 0, '', '', '管理员', '', '// 请在此处编写代码\n', '', 'Glowc', 'MonitorPush', 2, '2025-06-28 13:32:20', '2025-06-28 13:32:20', 'F', NULL, NULL, 'GLOWXQ'),
