.color("silver");\n  } else {\n    pen.color("bronze");\n  }\n  pen.fd(25);\n  pen.rt(45);\n}\n\n// 画一个螺旋\npen.move(400, 350);\npen.color("deepskyblue");\nfor (int i = 0; i < 20; i++) {\n  pen.fd(2 + i * 1.5);\n  pen.rt(30);\n}\n\npen.finish();', 'Glowc', '2025-04-26 07:39:23', '2025-06-07 19:27:50', 'F', 1, 1, 'GLOWXQ'),
('8', 1, 'aaa', 'admin', '// 请在此处编写代码\n', 'Glowc', '2025-04-26 12:18:55', '2025-06-07 19:27:50', 'F', 1, 1, 'GLOWXQ'),
('10', 1, 'glowxq', 'admin', '#include<iostream>\nusing namespace std;\nint main() {\n\n     return 0;\n}', 'OJ', '2025-06-23 01:30:38', '2025-06-23 01:30:38', 'F', 1, 1, 'GLOWXQ'),
('11', 1, 'glowxq', 'admin', '#include <bits/stdc++.h>\nusing namespace std;\nconst int N = 2e6 + 5;\nvector<int>e[N];\nint n, m, dfn[N], low[N], cnt, tot, id[N];\nstack<int>stk;\nint book[N];\n\nvoid tarjan(int x) {\n	dfn[x] = low[x] = ++cnt;\n	stk.push(x);\n	book[x] = 1;\n	for (auto v : e[x]) {\n		if (!dfn[v]) {\n			tarjan(v);\n			low[x] = min(low[x], low[v]);\n		} else if (book[v]) {\n			low[x] = min(low[x], dfn[v]);\n		}\n	}\n	if (low[x] == dfn[x]) {\n		tot++;\n		int v;\n		do {\n			v = stk.top();\n			stk.pop();\n			book[v] = 0;\n			id[v] = tot;\n		} while (x != v);\n	}\n}\n\nint main() {\n	cin >> m >> n;\n	for (int i = 1; i <= m; i++) {\n		char aa, bb;\n		int a,b;\n		cin >> aa >> a >> bb >> b;\n		if (aa == \'+\' && bb == \'+\') {\n			//!a->b  !b->a\n			e[a + n].push_back(b);\n			e[b + n].push_back(a);\n		} else if (aa == \'+\' && bb == \'-\') {\n			//!a->!b   b->a\n			e[a + n].push_back(b + n);\n			e[b].push_back(a);\n		} else if (aa == \'-\' && bb == \'+\') {\n			//a->b    !b->!a\n			e[a].push_back(b);\n			e[b + n].push_back(a + n);\n		} else if (aa == \'-\' && bb == \'-\') {\n			//a->!b   b->!a\n			e[a].push_back(b + n);\n			e[b].push_back(a + n);\n		}\n	}\n	for (int i = 1; i <= 2 * n; i++) {\n		if (!dfn[i])\n			tarjan(i);\n	}\n	for (int i = 1; i <= n; i++) {\n		if (id[i] == id[i + n]) {\n			cout << "IMPOSSIBLE" << endl;\n			exit(0);\n		}\n	}\n	for (int i = 1; i <= n; i++) {\n		if(id[i]<id[i+n])cout<<"+ ";\n		else cout<<"- ";\n	}\n	return 0;\n}', 'OJ', '2025-06-26 00:39:22', '2025-06-26 00:39:22', 'F', 1, 1, 'GLOWXQ'),
('12', 1, '管理员', '13667753053', '// 请在此处编写代码\npen.color(3);\nfor (int i = 0; i <4; i++) {\n    pen.fd(100);// code block\n    pen.rt(90);\n}\n\n', 'Glowc', '2026-01-02 09:53:07', '2026-01-02 09:53:07', 'F', 1, 1, 'GLOWXQ'),
