\n\\n// switch语句演示\\npen.move(350, 200);\\nfor (int i = 0; i < 4; i++) {\\n  switch (i) {\\n    case 0:\\n      pen.color(\\"red\\");\\n      pen.fd(35);\\n      break;\\n    case 1:\\n      pen.color(\\"blue\\");\\n      pen.fd(35);\\n      break;\\n    case 2:\\n      pen.color(\\"green\\");\\n      pen.fd(35);\\n      break;\\n    default:', -1, 'none', '', 937, '2025-06-23 20:31:18', '2025-06-23 20:31:18', 'F', 'GLOWXQ', NULL, NULL),
