(943, 1, '', '', 'admin', '27.38.202.97', 'com.glowxq.oj.code.controller.CodeMonitorController.listGroup()', '/api/code-monitor/listGroup', NULL, '', '', '{"groupId":"[Ljava.lang.String;@42501b09,"}', '', '{"code":"0000","message":"SUCCESS","data":[{"id":11,"monitorUserId":5,"overlayUserId":1,"monitorPhone":"13667753053","overlayPhone":"13667753053","monitorName":"啊啊啊宝宝","overlayName":"glowxq","monitorCode":"// 画笔测试代码 - C++语法风格\\npen.clear();\\npen.background(2);\\n\\n// 基本绘制操作 - for循环\\npen.color(1);\\npen.move(50, 50);\\n\\n// 使用for循环绘制正方形\\nfor (int i = 0; i < 4; i++) {\\n  pen.fd(80);\\n  pen.rt(90);\\n}\\n\\n// 使用for循环绘制五角星\\nfor (int i = 0; i < 5; i++) {\\n  pen.color(i);\\n  pen.circle(10);\\n  pen.triangleF(15);\\n  // Forward 100 pixels\\n  pen.fd(100);\\n  // Right turn by 144 degrees to form a star\\n  pen.rt(144);\\n}\\n\\n// 使用if-else条件判断\\npen.move(180, 50);\\npen.color(\\"blue\\");\\nfor (int i = 0; i < 8; i++) {\\n  if (i % 2 == 0) {\\n    pen.color(\\"blue\\");\\n  } else {\\n    pen.color(\\"green\\");\\n  }\\n  pen.fd(30);\\n  pen.rt(45);\\n}\\n\\n// 使用while循环\\npen.move(300, 50);\\npen.color(\\"purple\\");\\nint j = 0;\\nwhile (j < 6) {\\n  pen.fd(35);\\n  pen.rt(60);\\n  j++;\\n}\\n\\n// 使用do-while循环\\npen.move(90, 200);\\npen.color(\\"orange\\");\\nint k = 0;\\ndo {\\n  pen.circle(10 + k * 5);\\n  pen.move(90, 200 + k * 25);\\n  k++;\\n} while (k < 4);\\n\\n// 嵌套循环 - 绘制图案\\npen.move(220, 200);\\npen.color(\\"teal\\");\\nfor (int row = 0; row < 3; row++) {\\n  for (int col = 0; col < 3; col++) {\\n    if ((row + col) % 2 == 0) {\\n      pen.color(\\"teal\\");\\n      pen.circleF(10);\\n    } else {\\n      pen.color(\\"magenta\\");\\n      pen.squareF(15);\\n    }\\n    pen.move(220 + col * 25, 200 + row * 25);\\n  }\\n}\\n\\n// switch语句演示\\npen.move(350, 200);\\nfor (int i = 0; i < 4; i++) {\\n  switch (i) {\\n    case 0:\\n      pen.color(\\"red\\");\\n      pen.fd(35);\\n      break;\\n    case 1:\\n      pen.color(\\"blue\\");\\n      pen.fd(35);\\n      break;\\n    case 2:\\n      pen.color(\\"green\\");\\n      pen.fd(35);\\n      break;\\n    default:\\n      pen.color(\\"black\\");\\n      pen.fd(35);\\n      break;\\n  }\\n  pen.rt(90);\\n}\\n\\n// 三元运算符\\npen.move(130, 300);\\nfor (int i = 0; i < 6; i++) {\\n  pen.color(i % 2 == 0 ? \\"darkblue\\" : \\"darkred\\"', -1, 'none', '', 791, '2025-06-26 00:40:08', '2025-06-26 00:40:08', 'F', 'GLOWXQ', NULL, NULL),
(944, 1, '', '', 'admin', '27.38.202.97', 'com.glowxq.oj.code.controller.CodeRecordController.list()', '/api/code-record', NULL, '', '', '{"limit":"[Ljava.lang.String;@40aea10d,","page":"[Ljava.lang.String;@21357301,"}', '', '{"code":"0000","message":"SUCCESS","data":{"current":1,"limit":10,"totalPage":1,"total":10,"rows":[{"id":11,"userId":1,"name":"glowxq","username":"admin","code":"#include <bits/stdc++.h>\\nusing namespace std;\\nconst int N = 2e6 + 5;\\nvector<int>e[N];\\nint n, m, dfn[N], low[N], cnt, tot, id[N];\\nstack<int>stk;\\nint book[N];\\n\\nvoid tarjan(int x) {\\n\\tdfn[x] = low[x] = ++cnt;\\n\\tstk.push(x);\\n\\tbook[x] = 1;\\n\\tfor (auto v : e[x]) {\\n\\t\\tif (!dfn[v]) {\\n\\t\\t\\ttarjan(v);\\n\\t\\t\\tlow[x] = min(low[x], low[v]);\\n\\t\\t} else if (book[v]) {\\n\\t\\t\\tlow[x] = min(low[x], dfn[v]);\\n\\t\\t}\\n\\t}\\n\\tif (low[x] == dfn[x]) {\\n\\t\\ttot++;\\n\\t\\tint v;\\n\\t\\tdo {\\n\\t\\t\\tv = stk.top();\\n\\t\\t\\tstk.pop();\\n\\t\\t\\tbook[v] = 0;\\n\\t\\t\\tid[v] = tot;\\n\\t\\t} while (x != v);\\n\\t}\\n}\\n\\nint main() {\\n\\tcin >> m >> n;\\n\\tfor (int i = 1; i <= m; i++) {\\n\\t\\tchar aa, bb;\\n\\t\\tint a,b;\\n\\t\\tcin >> aa >> a >> bb >> b;\\n\\t\\tif (aa == \'+\' && bb == \'+\') {\\n\\t\\t\\t//!a->b  !b->a\\n\\t\\t\\te[a + n].push_back(b);\\n\\t\\t\\te[b + n].push_back(a);\\n\\t\\t} else if (aa == \'+\' && bb == \'-\') {\\n\\t\\t\\t//!a->!b   b->a\\n\\t\\t\\te[a + n].push_back(b + n);\\n\\t\\t\\te[b].push_back(a);\\n\\t\\t} else if (aa == \'-\' && bb == \'+\') {\\n\\t\\t\\t//a->b    !b->!a\\n\\t\\t\\te[a].push_back(b);\\n\\t\\t\\te[b + n].push_back(a + n);\\n\\t\\t} else if (aa == \'-\' && bb == \'-\') {\\n\\t\\t\\t//a->!b   b->!a\\n\\t\\t\\te[a].push_back(b + n);\\n\\t\\t\\te[b].push_back(a + n);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= 2 * n; i++) {\\n\\t\\tif (!dfn[i])\\n\\t\\t\\ttarjan(i);\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif (id[i] == id[i + n]) {\\n\\t\\t\\tcout << \\"IMPOSSIBLE\\" << endl;\\n\\t\\t\\texit(0);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif(id[i]<id[i+n])cout<<\\"+ \\";\\n\\t\\telse cout<<\\"- \\";\\n\\t}\\n\\treturn 0;\\n}","codeMode":"OJ"},{"id":10,"userId":1,"name":"glowxq","username":"admin","code":"#include<iostream>\\nusing namespace std;\\nint main() {\\n\\n     return 0;\\n}","codeMode":"OJ"},{"id":8,"userId":1,"name":"aaa","username":"admin","code":"// 请在此处编写代码\\n","codeMode":"Glowc"},{"id":7,"us', -1, 'none', '', 783, '2025-06-26 00:41:57', '2025-06-26 00:41:57', 'F', 'GLOWXQ', NULL, NULL),
