t\\texit(0);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif(id[i]<id[i+n])cout<<\\"+ \\";\\n\\t\\telse cout<<\\"- \\";\\n\\t}\\n\\treturn 0;\\n}","codeMode":"OJ"},{"id":10,"userId":1,"name":"glowxq","username":"admin","code":"#include<iostream>\\nusing namespace std;\\nint main() {\\n\\n     return 0;\\n}","codeMode":"OJ"},{"id":8,"userId":1,"name":"aaa","username":"admin","code":"// 请在此处编写代码\\n","codeMode":"Glowc"},{"id":7,"us', -1, 'none', '', 780, '2025-06-26 00:42:16', '2025-06-26 00:42:16', 'F', 'GLOWXQ', NULL, NULL),
