(1095, 1, '', '', '13667753053', '27.46.106.231', 'com.glowxq.oj.code.controller.CodeRecordController.list()', '/api/code-record', NULL, '', '', '{"limit":"[Ljava.lang.String;@2a62f42a,","page":"[Ljava.lang.String;@4756b5b2,"}', '', '{"code":"0000","message":"SUCCESS","data":{"current":1,"limit":10,"totalPage":1,"total":10,"rows":[{"id":11,"userId":1,"name":"glowxq","username":"admin","code":"#include <bits/stdc++.h>\\nusing namespace std;\\nconst int N = 2e6 + 5;\\nvector<int>e[N];\\nint n, m, dfn[N], low[N], cnt, tot, id[N];\\nstack<int>stk;\\nint book[N];\\n\\nvoid tarjan(int x) {\\n\\tdfn[x] = low[x] = ++cnt;\\n\\tstk.push(x);\\n\\tbook[x] = 1;\\n\\tfor (auto v : e[x]) {\\n\\t\\tif (!dfn[v]) {\\n\\t\\t\\ttarjan(v);\\n\\t\\t\\tlow[x] = min(low[x], low[v]);\\n\\t\\t} else if (book[v]) {\\n\\t\\t\\tlow[x] = min(low[x], dfn[v]);\\n\\t\\t}\\n\\t}\\n\\tif (low[x] == dfn[x]) {\\n\\t\\ttot++;\\n\\t\\tint v;\\n\\t\\tdo {\\n\\t\\t\\tv = stk.top();\\n\\t\\t\\tstk.pop();\\n\\t\\t\\tbook[v] = 0;\\n\\t\\t\\tid[v] = tot;\\n\\t\\t} while (x != v);\\n\\t}\\n}\\n\\nint main() {\\n\\tcin >> m >> n;\\n\\tfor (int i = 1; i <= m; i++) {\\n\\t\\tchar aa, bb;\\n\\t\\tint a,b;\\n\\t\\tcin >> aa >> a >> bb >> b;\\n\\t\\tif (aa == \'+\' && bb == \'+\') {\\n\\t\\t\\t//!a->b  !b->a\\n\\t\\t\\te[a + n].push_back(b);\\n\\t\\t\\te[b + n].push_back(a);\\n\\t\\t} else if (aa == \'+\' && bb == \'-\') {\\n\\t\\t\\t//!a->!b   b->a\\n\\t\\t\\te[a + n].push_back(b + n);\\n\\t\\t\\te[b].push_back(a);\\n\\t\\t} else if (aa == \'-\' && bb == \'+\') {\\n\\t\\t\\t//a->b    !b->!a\\n\\t\\t\\te[a].push_back(b);\\n\\t\\t\\te[b + n].push_back(a + n);\\n\\t\\t} else if (aa == \'-\' && bb == \'-\') {\\n\\t\\t\\t//a->!b   b->!a\\n\\t\\t\\te[a].push_back(b + n);\\n\\t\\t\\te[b].push_back(a + n);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= 2 * n; i++) {\\n\\t\\tif (!dfn[i])\\n\\t\\t\\ttarjan(i);\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif (id[i] == id[i + n]) {\\n\\t\\t\\tcout << \\"IMPOSSIBLE\\" << endl;\\n\\t\\t\\texit(0);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif(id[i]<id[i+n])cout<<\\"+ \\";\\n\\t\\telse cout<<\\"- \\";\\n\\t}\\n\\treturn 0;\\n}","codeMode":"OJ"},{"id":10,"userId":1,"name":"glowxq","username":"admin","code":"#include<iostream>\\nusing namespace std;\\nint main() {\\n\\n     return 0;\\n}","codeMode":"OJ"},{"id":8,"userId":1,"name":"aaa","username":"admin","code":"// 请在此处编写代码\\n","codeMode":"Glowc"},{"id":7,"us', -1, 'none', '', 27, '2025-07-29 01:08:10', '2025-07-29 01:08:10', 'F', 'GLOWXQ', NULL, NULL),
