or (int i = 1; i <= 2 * n; i++) {\\n\\t\\tif (!dfn[i])\\n\\t\\t\\ttarjan(i);\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif (id[i] == id[i + n]) {\\n\\t\\t\\tcout << \\"IMPOSSIBLE\\" << endl;\\n\\t\\t\\texit(0);\\n\\t\\t}\\n\\t}\\n\\tfor (int i = 1; i <= n; i++) {\\n\\t\\tif(id[i]<id[i+n])cout<<\\"+ \\";\\n\\t\\telse cout<<\\"- \\";\\n\\t}\\n\\treturn 0;\\n}","codeMode":"OJ"},{"id":10,"userId', -1, 'none', '', 12, '2026-01-03 16:59:24', '2026-01-03 16:59:24', 'F', 'GLOWXQ', NULL, NULL),
