INSERT INTO `user_problem` (`id`, `user_id`, `problem_id`, `problem_key`, `problem_title`, `judge_id`, `judge_status`, `score`, `code`, `options`, `flow_image`, `problem_type`, `create_time`, `update_time`, `del_flag`, `create_id`, `update_id`, `tenant_id`) VALUES
(1, 1, 54, 'Q1031', '[GESP202406 三级]  寻找倍数', 222, 4, 0, '对于每组测试用例，如果存在 $i(1\\leq i\\leq n)$ ，满足对于所有 $k(1\\leq k\\leq n)$ $a_i$ 是 $a_k$ 的倍数，输出 `Yes`，否则输出 `No`。\n', '', '', 'Programmer', '2025-04-18 17:53:42', '2025-06-07 19:33:54', 'F', NULL, NULL, 'GLOWXQ'),
(2, 1, 56, 'Q1078', '[GESP202406 五级] 小杨的幸运数字', 227, 4, 0, '对于每组测试用例，如果存在 $i(1\\leq i\\leq n)$ ，满足对于所有 $k(1\\leq k\\leq n)$ $a_i$ 是 $a_k$ 的倍数，输出 `Yes`，否则输出 `No`。\n对于每组测试用例，如果存在 $i(1\\leq i\\leq n)$ ，满足对于所有 $k(1\\leq k\\leq n)$ $a_i$ 是 $a_k$ 的倍数，输出 `Yes`，否则输出 `No`。\n对于每组测试用例，如果存在 $i(1\\leq i\\leq n)$ ，满足对于所有 $k(1\\leq k\\leq n)$ $a_i$ 是 $a_k$ 的倍数，输出 `Yes`，否则输出 `No`。\n对于每组测试用例，如果存在 $i(1\\leq i\\leq n)$ ，满足对于所有 $k(1\\leq k\\leq n)$ $a_i$ 是 $a_k$ 的倍数，输出 `Yes`，否则输出 `No`。\n', '', '', 'Programmer', '2025-04-18 20:45:54', '2025-06-07 19:33:54', 'F', NULL, NULL, 'GLOWXQ'),
(3, 1, 139, 'Q1079', '[GESP202406 五级] 黑白格', 242, 4, 0, '#include <bits/stdc++.h>\nusing namespace std;\nint main() {\n\n    return 0;\n}', '', '', 'Programmer', '2025-06-10 02:19:48', '2025-06-10 02:19:48', 'F', NULL, NULL, 'GLOWXQ'),
(4, 1, 138, 'Q1027', '[GESP202406 一级]  休息时间', 250, 4, 0, '#include<iostream>\nusing namespace std;\nint main() {\n\n     return 0;\n}', '', '', 'Programmer', '2025-06-10 02:29:07', '2025-06-10 02:29:07', 'F', NULL, NULL, 'GLOWXQ'),
(5, 1, 387, 'T1338', '小 Z 的逆序对', 363, -2, 0, 'sadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfasadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfasadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfasadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfasadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfasadfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfsdfa', '', '', 'Programmer', '2025-08-03 23:21:08', '2025-08-03 23:21:08', 'F', NULL, NULL, 'GLOWXQ'),
(6, 1, 387, 'T1338', '小 Z 的逆序对', 364, -1, 0, '#include <iostream>\nusing namespace std;\nint a[1000005];\nint main() {\n	int t,n,max=0;\n	cin>>t;\n	for(int i=1;i<=t;i++){\n		cin>>n;\n		int flag=1;\n		for(int j=1;j<=n;j++){\n			cin>>a[j];\n		}\n        max=0;\n		for(int j=1;j<=n;j++)\n			if(a[j]>max){\n				max=a[j];\n			}\n			\n		\n		for(int j=1;j<=n;j++){\n			if(max%a[j]!=0){\n				flag=0;\n				break;\n			}\n		}\n				\n		\n		\n		if(flag){\n			cout<<"YES"<<endl;\n		}\n		else{\n			cout<<"NO"<<endl;\n		}\n	}\n	\n	\n    return 0;\n}\n', '', '', 'Programmer', '2025-08-03 23:21:41', '2025-08-03 23:21:41', 'F', NULL, NULL, 'GLOWXQ'),
(7, 8, 391, 'GESP1211', '[GESP202506五级] 最大公因数', 366, 4, 0, '#include <iostream>\nusing namespace std;\nint a[1000005];\nint main() {\n	int t,n,max=0;\n	cin>>t;\n	for(int i=1;i<=t;i++){\n		cin>>n;\n		int flag=1;\n		for(int j=1;j<=n;j++){\n			cin>>a[j];\n		}\n        max=0;\n		for(int j=1;j<=n;j++)\n			if(a[j]>max){\n				max=a[j];\n			}\n			\n		\n		for(int j=1;j<=n;j++){\n			if(max%a[j]!=0){\n				flag=0;\n				break;\n			}\n		}\n				\n		\n		\n		if(flag){\n			cout<<"YES"<<endl;\n		}\n		else{\n			cout<<"NO"<<endl;\n		}\n	}\n	\n	\n    return 0;\n}\n', '', '', 'Programmer', '2025-08-03 23:53:54', '2025-08-03 23:53:54', 'F', NULL, NULL, 'GLOWXQ'),
(8, 1, 388, 'HOL041', '数组合并', 386, -2, 0, '##include <bits/stdc++.h>\nusing namespace std;\nint main(){\n    int a [100000],b[1000];\n    int n,n1;\n    cin >>n>>n1;\n    for(int i =0;i<n+n1;i++){\n        cin >>a[i];\n    }\n        for(int i =0;i<n+n1;i++){\n        cout<<a[i]<<" ";\n    }\n}', '', '', 'Programmer', '2026-01-03 17:03:16', '2026-01-03 17:03:16', 'F', NULL, NULL, 'GLOWXQ'),
(9, 1, 388, 'HOL041', '数组合并', 387, -1, 0, '#include <bits/stdc++.h>\nusing namespace std;\nint main(){\n    int a [100000],b[1000];\n    int n,n1;\n    cin >>n>>n1;\n    for(int i =0;i<n+n1;i++){\n        cin >>a[i];\n    }\n        for(int i =0;i<n+n1;i++){\n        cout<<a[i]<<" ";\n    }\n}', '', '', 'Programmer', '2026-01-03 17:03:25', '2026-01-03 17:03:25', 'F', NULL, NULL, 'GLOWXQ');
